// ══════════════════════════════════════════════════════════════════════════════
// openPrintWindow — renders print content in a full-screen iframe (blob URL)
// ══════════════════════════════════════════════════════════════════════════════
//
// FOUR attempts got us here. Each fixed the previous one's failure but exposed
// the next. This is the combination that satisfies every constraint at once.
//
//   Attempt 1  document.write on about:blank
//     Chrome treats dynamically written about:blank as a "null origin"; inline
//     onclick handlers and window.print() are silently blocked.
//
//   Attempt 2  blob: URL popup (window.open)
//     A blob: URL IS a real same-origin document, so buttons and print work AND
//     charset=utf-8 renders ₦ / — / · / 🖨 correctly. BUT Chrome's focus-
//     stealing prevention opens the popup *behind* the main window; the user
//     cannot see it and clicks the app underneath instead.
//
//   Attempt 3  DOM overlay (DOMParser + innerHTML in the current document)
//     No popup, buttons visible — but two regressions:
//       • MOJIBAKE returned. The overlay reuses the in-page document's decoding
//         instead of a blob's authoritative charset=utf-8, so ₦/—/·/🖨 broke.
//       • BLACK PRINT. window.print() printed the whole page; the app's dark
//         theme background bled onto the paper behind the (dark) text.
//
//   Attempt 4 (this one)  full-screen IFRAME whose src is the blob: URL
//     • blob: + charset=utf-8  → encoding is correct (Attempt 2's win, kept).
//     • it's an <iframe> in the CURRENT window, not a popup → always visible,
//       no popup blocker, no focus-stealing (Attempt 3's win, kept).
//     • it's a real same-origin document → the toolbar's Print button and the
//       printBootstrap auto-print script run normally (Attempt 1 fixed).
//     • printing is scoped to the iframe's own white document → the app's dark
//       background can never reach the paper (Attempt 3's black-print fixed).
//
// Usage (unchanged at all 40 call sites):
//   openPrintWindow(`<!DOCTYPE html><html>...${ printBootstrap() }...</html>`);
//
// ══════════════════════════════════════════════════════════════════════════════
export function openPrintWindow(html) {
  // ── Inject <meta charset="utf-8"> (belt-and-suspenders; the blob MIME type
  //    below is the authoritative declaration) and a print-color-adjust rule so
  //    table-header / totals-row background colours print even when the user has
  //    Chrome's "Background graphics" option unchecked.
  let doc = html;
  if (!/<meta\s[^>]*charset/i.test(doc)) {
    doc = doc.replace(/(<head[^>]*>)/i, '$1<meta charset="utf-8">');
  }
  doc = doc.replace(
    /(<head[^>]*>)/i,
    '$1<style>*{-webkit-print-color-adjust:exact;print-color-adjust:exact}</style>'
  );

  // ── The blob: URL is a real, same-origin document decoded as UTF-8. This is
  //    the piece that renders ₦ — · 🖨 correctly (proven in production).
  const blob = new Blob([doc], { type: 'text/html;charset=utf-8' });
  const url  = URL.createObjectURL(blob);

  // ── A full-screen iframe in the CURRENT window — not a popup. Always visible,
  //    never blocked, never opens behind. background:#fff so nothing shows
  //    through while it loads.
  const frame = document.createElement('iframe');
  frame.id = '__slot_print_frame';
  frame.setAttribute('title', 'Print preview');
  frame.style.cssText =
    'position:fixed;top:0;left:0;width:100vw;height:100vh;border:0;margin:0;' +
    'z-index:2147483647;background:#fff';
  frame.src = url;

  // ── Cleanup: remove the iframe and free the blob.
  function cleanup() {
    document.getElementById('__slot_print_frame')?.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // ── Print/close logic lives HERE, in the parent app's bundled JS, not as
  //    inline <script>/onclick inside the blob document. The blob inherits
  //    this page's CSP (script-src 'self'), so inline handlers placed inside
  //    the frame's own HTML would be silently blocked. Code running here is
  //    part of the app bundle and is always allowed.
  //
  //    Same three-layer guarantee as before, just relocated:
  //      1. the toolbar's Print/Close buttons, wired via addEventListener
  //      2. a timer shortly after the frame loads (lets the logo/table lay
  //         out — printing instantly can produce a sheet with a blank header)
  //      3. an unconditional fallback timer that fires even if 'load' never
  //         arrives on the iframe
  let printed = false;
  function doPrint() {
    if (printed) return;
    printed = true;
    try { frame.contentWindow.focus(); } catch (e) {}
    try { frame.contentWindow.print(); } catch (e) {}
  }

  frame.onload = () => {
    try {
      const cdoc = frame.contentDocument;
      const goBtn = cdoc && cdoc.querySelector('.print-toolbar .go');
      const closeBtn = cdoc && cdoc.querySelector('.print-toolbar .close');
      if (goBtn) goBtn.addEventListener('click', (e) => { e.preventDefault(); doPrint(); });
      if (closeBtn) closeBtn.addEventListener('click', (e) => { e.preventDefault(); cleanup(); });
      // Bring keyboard/print focus into the frame so the auto-print dialog and
      // the buttons respond immediately.
      frame.contentWindow.focus();
    } catch (e) { /* same-origin blob: should never throw, but never block UI */ }
    setTimeout(doPrint, 300);
  };
  setTimeout(doPrint, 1500);   // fires even if the iframe's 'load' never arrives

  document.body.appendChild(frame);
  return { frame, close: cleanup };
}

// ══════════════════════════════════════════════════════════════════════════════
// printBootstrap — make a generated print window actually print
// ══════════════════════════════════════════════════════════════════════════════
//
// THE BUG THIS REPLACES (found 2026-08-04, reported by the terminal team)
//
// Every print in this app was built the same way: open a blank window,
// document.write() the HTML, document.close(), and end the markup with
//
//     <script>window.onload=()=>window.print()<\/script>
//
// That handler frequently never fires. document.close() finishes the document
// immediately, so by the time the inline script runs the `load` event has
// often already been dispatched — assigning window.onload afterwards attaches
// a listener to an event that is never coming. The user gets a page with no
// print dialog and no button, which is exactly what was reported: "immediately
// I click print, it pops up this page which has nowhere to click print."
//
// It was in 34 places across 14 modules, so it was fixed here rather than
// once at the call site.
//
// THREE LAYERS, so a print always reaches the user:
//   1. a visible toolbar with Print and Close buttons — .no-print keeps it off
//      the paper. Even if every automatic trigger fails, there is a button.
//   2. plain timers — never requestAnimationFrame. rAF does not fire in a
//      window that is not being painted (a popup opening behind the main
//      window), which stalled the first version of this fix entirely. A short
//      delay still runs first so images — the SLOT logo especially — have laid
//      out; printing instantly yields a sheet with a blank header.
//   3. document.readyState is checked instead of trusting onload, and an
//      unconditional timer fires even if 'load' never arrives. Every trigger
//      calls doPrint() directly, and the "already printed" guard sits on that
//      function — so no trigger can consume the flag and leave the others dead.
//
// @param {object} opts
//   landscape — wide tables (10+ columns) are unreadable on portrait A4
//   pageSize  — 2026-08-15: override for non-A4 output (e.g. a CR80 ID badge).
//               Any valid CSS @page size value, e.g. '53.98mm 85.6mm'. Falls
//               back to the existing A4 portrait/landscape behaviour when omitted,
//               so all ~40 existing call sites are unaffected.
//   margin    — 2026-08-15: override for the printed-page margin. The 12mm
//               default below was tuned for A4 reports; a card-sized pageSize
//               needs a much smaller margin or the content won't fit.
// ══════════════════════════════════════════════════════════════════════════════
export function printBootstrap({ landscape = false, pageSize = null, margin = null } = {}) {
  const sizeRule = pageSize || `A4 ${landscape ? 'landscape' : 'portrait'}`;
  const printMargin = margin || '12mm';
  return `
  <style>
    /* ── 2026-08-06, at the GM's request ──────────────────────────────────
       The line reading "SLOT Engineering — ERP" at the top of every printout,
       along with the date, the yemicoreerp.web.app URL and the page number,
       is NOT part of the document we generate — it is Chrome's own print
       header/footer, which prints the page title and address automatically.
       It cannot be deleted from our markup.

       Setting the page margin to zero leaves Chrome nowhere to draw that
       block, so it is omitted. The paper margin is then reapplied as body
       padding below, with !important because several modules set their own
       @media print body padding and this style block is emitted last.

       Trade-off accepted by the GM: page numbers belong to the same block
       and disappear along with it. */
    @page { size: ${sizeRule}; margin: 0; }
    .print-toolbar{position:fixed;top:0;left:0;right:0;z-index:9999;display:flex;gap:10px;
      align-items:center;justify-content:flex-end;padding:10px 16px;background:#0F3A1A;
      box-shadow:0 2px 8px rgba(0,0,0,.25);font-family:'Segoe UI',Arial,sans-serif}
    .print-toolbar span{margin-right:auto;color:rgba(255,255,255,.75);font-size:12px}
    .print-toolbar button{border:none;border-radius:6px;padding:7px 16px;font-size:13px;
      font-weight:600;cursor:pointer}
    .print-toolbar .go{background:#2FA84F;color:#fff}
    .print-toolbar .close{background:transparent;color:#fff;border:1px solid rgba(255,255,255,.4)}
    body{padding-top:56px !important}
    /* Paper margin restored here, since @page no longer supplies one.
       12mm all round matches what the 10mm @page margin plus the old body
       padding gave, so nothing shifts noticeably on the printed sheet.
       Overridable via the margin param for small pageSize output (e.g. an
       ID card), where 12mm on every side would eat most of the card. */
    @media print{.print-toolbar{display:none !important}body{padding:${printMargin} !important}}
  </style>
  <div class="print-toolbar no-print">
    <span>Use your browser's print dialog to change paper size, orientation or save as PDF.</span>
    <button class="go" type="button">🖨 Print</button>
    <button class="close" type="button">Close</button>
  </div>`;
  // 2026-08-05, third pass. Deliberately NO inline <script> and NO onclick=""
  // attributes in this markup any more.
  //
  // openPrintWindow (below) now renders this into an iframe whose src is a
  // blob: URL. Chrome has a blob: document inherit the CSP of the page that
  // created it — so with `script-src 'self'` and no 'unsafe-inline' set in
  // firebase.json, any inline script or inline event handler placed in THIS
  // string is silently blocked. The frame itself still loads fine (that's a
  // separate directive, frame-src) but the auto-print timer never runs and
  // the toolbar buttons do nothing when clicked — a new, quieter version of
  // the original "print does nothing" bug.
  //
  // All print/close behaviour now lives in openPrintWindow's frame.onload,
  // which runs as part of the app's own bundled JS (script-src 'self') and
  // is therefore never blocked, regardless of how strict the CSP gets.
}
